command:
set -euo pipefail
LIVE=/home/ai-core-node/.claude/star/visual/buehne.html
COMMIT=628cfbdf5613fc792be47f1c270860a879e45a08
REPO=/home/ai-core-node/clay-global-research-entity
TMP=$(mktemp -d /tmp/avatar-v11-shadow.XXXXXX)
trap 'rm -rf "$TMP"' EXIT
echo SERVICE=$(systemctl --user is-active frankenstein-buehne.service)
echo WINDOWS=$(DISPLAY=:0 xdotool search --name '^FranKenstein -- live$' 2>/dev/null | wc -l)
echo LIVE_SHA_BEFORE=$(sha256sum "$LIVE" | awk '{print $1}')
