[ "$(sha256sum "$LIVE" | awk '{print $1}')" = cfaefcd2719d7680d8b0a532aa6fae9c2920e022ab3626d18de073eb87a80cdb ] || { echo LIVE_CAS_DRIFT; exit 40; }
