git -C "$REPO" show FETCH_HEAD:research_entity/coordination/upgrade_avatar_microexpr_v11.py > "$TMP/upgrade.py"
cp "$LIVE" "$TMP/buehne.html"
python3 - "$TMP/upgrade.py" "$TMP/buehne.html" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1]); target=sys.argv[2]
s=p.read_text(); old="LIVE = Path('/home/ai-core-node/.claude/star/visual/buehne.html')"; new='LIVE = Path('+repr(target)+')'
assert s.count(old)==1, s.count(old)
p.write_text(s.replace(old,new,1))
PY
python3 "$TMP/upgrade.py"
echo SHADOW_SHA=$(sha256sum "$TMP/buehne.html" | awk '{print $1}')
echo V11_BEGIN=$(grep -c 'FRANK_MICROEXPR_V11 BEGIN' "$TMP/buehne.html")
