echo LIVE_SHA_AFTER=$(sha256sum "$LIVE" | awk '{print $1}')
[ "$(sha256sum "$LIVE" | awk '{print $1}')" = cfaefcd2719d7680d8b0a532aa6fae9c2920e022ab3626d18de073eb87a80cdb ] || { echo SHADOW_MUTATED_LIVE; exit 41; }
echo SHADOW_PREFLIGHT_PASS
